// Checks the manifest value rules of one StaticRulesRecord.
inline bool VoxRlIsValidStaticRulesRecord(const StaticRulesRecord& row)
{
    if (row.operationalMaxRecruitTurns < 0) return false;
    if (row.tacticalMapTempZoneTurns < 0) return false;
    if (row.baseUnitUpgradeCost < 0) return false;
    if (row.unitUpgradeCostVisibleDivisor < 1) return false;
    if (row.aiGoldPriorityUnit < 0) return false;
    if (row.aiOperationalPercentHealthForOperation < 0) return false;
    if (row.aiGoldPriorityUpgradeBase < 0) return false;
    if (row.aiGoldPriorityUpgradePerFlavorPoint < 0) return false;
    if (row.minGameTurnsElapsedToTestVictory < 0) return false;
    if (row.worldSize < 0) return false;
    if (row.artifactResource < -1) return false;
    if (row.hiddenArtifactResource < -1) return false;
    if (row.barbarianReleaseTurn < -1) return false;
    return true;
}

// Checks every StaticRulesRecord row and the manifest uniqueness rules across rows.
inline bool VoxRlAreValidStaticRulesRecordRows(const StaticRulesRecord* rows, u32 count)
{
    for (u32 index = 0; index < count; ++index)
    {
        if (!VoxRlIsValidStaticRulesRecord(rows[index])) return false;
    }
    return true;
}

