// Checks the manifest value rules of one UnitRecord.
inline bool VoxRlIsValidUnitRecord(const UnitRecord& row)
{
    if (row.deployFromOperationTurn < -100) return false;
    if (row.unitType < 0 || row.unitType > 65535) return false;
    if (row.plotIndex < 0 || row.plotIndex > 32767) return false;
    if (row.damage < 0 || row.damage > 65535) return false;
    if (row.moves < -32768 || row.moves > 32767) return false;
    if (row.maxMoves < 0 || row.maxMoves > 65535) return false;
    if (row.baseMoves < 0 || row.baseMoves > 255) return false;
    if (row.reconPlotIndex < -1) return false;
    if (row.level < 0 || row.level > 255) return false;
    if (row.power < 0 || row.power > 65535) return false;
    if (row.baseCombatStrength < 0 || row.baseCombatStrength > 65535) return false;
    if (row.actualHealRate < -32768 || row.actualHealRate > 32767) return false;
    if (row.baseMovesEmbarked < 0 || row.baseMovesEmbarked > 255) return false;
    if (row.baseRangedCombatStrength < 0 || row.baseRangedCombatStrength > 65535) return false;
    if (row.unitCombatType < -1 || row.unitCombatType > 63) return false;
    return true;
}

